seq = ''.join(l.strip() for l in lines if not l.startswith('>')).upper()
N=len(seq)

def tandem_scan(s, pmin, pmax, mincopies):
    n=len(s); found=[]
    for p in range(pmin,pmax+1):
        j=0
        while j+p<=n:
            unit=s[j:j+p]; cnt=1; k=j+p
            while s[k:k+p]==unit:
                cnt+=1; k+=p
            if cnt>=mincopies:
                found.append((j,k,p,cnt,unit)); j=k
            else:
                j+=1
    return found

