lines = open('region.fasta').read().split('\n')
seq = ''.join(l.strip() for l in lines if not l.startswith('>')).upper()
N=len(seq)
comp={'A':'T','T':'A','G':'C','C':'G'}
rc=''.join(comp[b] for b in reversed(seq))
stops={'TAA','TAG','TGA'}

def all_orfs(s, strand, min_aa=60):
    res=[]; L=len(s)
    for f in range(3):
        j=f; start=None
        while j+3<=L:
            cod=s[j:j+3]
            if start is None:
                if cod=='ATG': start=j
            else:
                if cod in stops:
                    if (j+3-start)>=min_aa*3: res.append((strand,start,j+3,j+3-start))
                    start=None
            j+=3
        if start is not None and (L-start)>=min_aa*3:
            res.append((strand,start,L,L-start))
    return res

orfs=[]
orfs+=all_orfs(seq,'+')
orfs+=all_orfs(rc,'-')
orfs.sort(key=lambda x:-x[3])
for (st,a,b,ln) in orfs:
    if st=='+':
        print("%s  1-based %d-%d  aa=%d" % (st, a+1, b, ln//3))
    else:
        # convert rc coords to genomic (0-based): pos i in rc -> N-1-i
        ga=N-1-(b-1); gb=N-1-a  # 0-based start,end on genome; strand minus
        print("%s  genomic 1-based %d-%d  aa=%d" % (st, ga+1, gb, ln//3))
